import {ATTRIBUTES, emptyCharacter} from './model.js';
const mapId='caldris';
const locations=[
 ['capital','Caldris Real',44,40,'Capital de 70 mil almas. Barreira seletiva ativa: pessoas circulam; exércitos externos não entram. Carta de sucessão com 43 selos.'],
 ['brennford','Brennford',65,52,'Vila de cerca de 40 casas, selada por barreira absoluta. Capela de pedra negra anterior à vila. Comando de Lyra Ashvale.'],
 ['durnholm','Durnholm',65,15,'Montanhas Cinzas. 8.840 pessoas ressuscitadas. Borin mantém a ordem, Vesk investiga os deuses e Elric trata da crise jurídica.'],
 ['thornwick','Thornwick',90,52,'Capital da Marca Oriental. Catedral das Passagens entregue sem condições. 1.200 curados. Cripta dos Nomes esvaziada. Comando de Varrick Thorne.'],
 ['greymoor','Estrada de Greymoor',40,55,'Oriane, Caedmon, Mallory e a escolta seguem para interceptar o Duque Velarde em quatro dias. Posição da comitiva aproximada.'],
 ['velmoor','Floresta de Velmoor',57,71,'Árvores gigantes de casca cinzenta. Local da descida de Momo. Lobos-cinzentos e esquilos-sêxtuplos. Sul e oeste de Brennford.'],
 ['ponte','Ponte de Pedra Velha',75,55,'Sobre o Rio Ashen, a 4 km a leste de Brennford, com doze passos de largura. Local da rendição do Marquês.'],
 ['dunmere','Dunmere',82,54,'Posto de troca de cavalos. Acampamento registrado da Companhia do Corvo Negro; a irmã de Vesk vive aqui.'],
 ['trigo','Campos de trigo-azulado',73,48,'O sulco aberto pela espada arremessada por Borin permanece visível.'],
 ['velarde','Ducado Velarde',23,38,'Duque de 61 anos, veterano de três guerras. Oito mil homens marcham; a filha Oriane pretende interceptá-lo.'],
 ['harrow','Terras de Harrow',29,25,'Seis mil homens em marcha. O texto da campanha indica onze dias; a inscrição do mapa indica oito.'],
 ['brandt','Domínio Brandt',32,76,'Ilsa Brandt lidera quatro mil homens. Considerada a melhor comandante viva de Caldris.'],
 ['arena','Campo do Leão',49,44,'Arena proposta fora dos muros de Caldris Real. Posição editorial aproximada; o mapa não identifica o campo.'],
 ['hallow','Hallow',22,60,'Terras tribais independentes, origem de Yuki e cenário da Revolta.']
].map(([id,name,x,y,description])=>({id,name,x,y,description,mapId}));
function character(id,name,image,locationId,role,age,rank,summary,relations,loyalty,faction,attributes={},notes='') {
 const loc=locations.find(l=>l.id===locationId);
 return {...emptyCharacter(),id,name,image:image?`assets/${image}.webp`:'',portrait:image?`assets/${image}-portrait.webp`:'',locationId,role,age,rank,summary,relations,loyalty,faction,notes,positions:loc?{[mapId]:{x:loc.x,y:loc.y}}:{},attributes:Object.fromEntries(ATTRIBUTES.map(a=>[a,attributes[a]??null]))};
}
const all100=Object.fromEntries(ATTRIBUTES.map(a=>[a,100]));
const characters=[
 character('momo','Monzai Dragon','MOnzai','capital','Rainha de Caldris · A Voz Que Devolve','17','9.999.999 · registro público 0','Morreu em outro mundo e tomou o poder de Aethran durante a bênção. Carrega duas almas divinas: Aethran, de memórias nítidas, e a entidade de Durnholm, de memórias turvas. Objetivo declarado: absorver todos os deuses. Curou Brennford, 1.200 pessoas em Thornwick e ressuscitou 8.840 em Durnholm. Obteve o reino por carta legal, sem matar súditos.\n\nAgora: pátio norte do castelo, às 02h. Exausta após sete dias de extrações; leva a mão ao peito sem perceber. Politicamente protegida pela Carta e pela barreira. Nunca matou um ser humano. Sua linguagem de posse é questionada pelos aliados.','Noiva de Lyra Ashvale e Celine Auvret. Borin é uma figura protetora. Vesk investiga as almas divinas; Yuki é sua protegida.','A si mesma e aos seus leais','Coroa / Conselho',Object.fromEntries(ATTRIBUTES.map(a=>[a,9999999])),'Os valores reais são informação do mestre: ninguém neste mundo consegue percebê-los. Duas almas absorvidas; a identidade Segundo/Terceiro ainda é incerta.'),
 character('celine','Celine Auvret','Celina','capital','Autoridade eclesiástica da Marca','20 e poucos; idade a confirmar','100 em tudo','Clériga privada da visão pelo preço sagrado. Monzai devolveu seus olhos após dezenove anos de cegueira. Arrancou a faixa diante da comunidade e tornou-se prova viva do colapso da antiga Igreja. Ofereceu lealdade com o direito de confrontar a rainha se ela repetir Aethran.\n\nAgora: ao lado de Monzai no pátio de Caldris. Rank 100 ainda desconhecido da corte; o torneio pode revelar o segredo. Guarda a última conta de vidro do rosário.','Noiva de Monzai; aliada de Lyra. Vítima do ritual de Mallory.','Total, condicional e vigilante','Antiga Igreja / Coroa',all100,'Continuidade: o compêndio diz “20 e poucos”, o diálogo diz 26 e o histórico (13 + 19 anos) sugere 32. A idade permanece em aberto, sem correção automática.'),
 character('lyra','Lyra Ashvale','Lyra','brennford','Arqueira · Braço direito · Comando da vila','17','100 em tudo','Encontrou Momo na Floresta de Velmoor e se colocou à frente dela contra três lobos. Pagou seu registro na Guilda. Exigiu o direito de dizer quando a rainha erra e já o exerceu sete vezes. Em Durnholm contou quatro mil extrações e sustentou Momo durante o ritual. Ajudou a impedir a morte de Hale.\n\nAgora: comanda Brennford. Antes era Rank 22, Destreza 34. Arco de aço de Dunmere, capa verde-musgo e anel com flecha.','Noiva de Monzai; aliada de Celine e Yuki.','Absoluta e desobediente','Brennford / Coroa',all100),
 character('borin','Borin Ironhall','Borin','durnholm','Capitão da Guarda','52','100 em tudo','Veterano sobrevivente de Durnholm. Por dezessete anos carregou uma cicatriz de fogo e a culpa de ter fugido. Momo apagou a cicatriz. Foi o primeiro a afirmar em público que estava com ela. Arremessou uma espada por quatro quilômetros. Desobedeceu uma ordem direta em Durnholm para protegê-la.\n\nAgora: impõe ordem na cidade ressuscitada. Antes: Rank 61, Vitalidade 63. Tem uma filha em Thornwick.','Protetor paternal de Monzai. Trabalha com Vesk e Elric.','Absoluta, com uma linha que não cruza','Guarda / Coroa',all100),
 character('vesk','Aurelian Vesk','Vesk','durnholm','Inteligência · Investigador','35','87','Ex-Inquisidor por doze anos. Construído, não crescido: alguém escreveu seus números. Investiga o silêncio das unções há quatro anos. Enviado para anular Monzai, escolheu compreender antes de agir. Descobriu que a lâmina era desnecessária para devolver as almas de Durnholm.\n\nAgora: investiga a diferença entre as memórias divinas e o Terceiro. Condição autoimposta: relata, não executa. Pediu para ser demitido se começar a encontrar traidores demais.','Nunca jurou lealdade. Tem uma irmã em Dunmere. Colabora com Elric e Borin.','Não jurada; independência preservada','Inteligência do reino',{'Destreza':87}),
 character('elric','Elric Vance','Elric','durnholm','Arquivista-Mor','30','Inteligência 38','Registra os fatos desde o primeiro dia, inclusive o que pode condená-lo. Nunca se ajoelhou. Mantém o Apêndice C.\n\nAgora: enfrenta a crise jurídica dos 8.840 ressuscitados de Durnholm e compila o compêndio do dia 26 da Lua Pálida.','Acompanha Vesk e Borin; cronista de Monzai.','Ao registro e à verdade','Arquivos do reino',{'Inteligência':38}),
 character('yuki','Yuki','Yuki','durnholm','Vigia de perímetro','16','Agilidade 61','Garota-lobo das tribos de Hallow. Capturada aos dez durante a Revolta e mantida por seis invernos numa jaula em Thornwick. Monzai abriu sua coleira. Pediu que sua história não fosse resumida apenas como crueldade. Ensinou a frase de Hallow: “Você já não está lá.”\n\nAgora: recebeu o primeiro cargo de sua vida, vigia de perímetro. Subnutrida, começa a descobrir que pode escolher. Pode querer entrar no campeonato sem experiência de luta.','Protegida de Monzai; companheira de Lyra e Celine. Varrick foi seu captor.','Intensa; marcada pelo trauma','Hallow / Coroa',{'Agilidade':61}),
 character('varrick','Varrick Thorne','Varrick','thornwick','Marquês da Marca Oriental','51','Inteligência 66','Governante cruel e pragmático: dobrou o dízimo na seca, enviou meninos ao Corvo Negro e manteve Yuki cativa. Cancelou a ordem de queimar Brennford e foi pessoalmente à ponte. Admitiu por escrito que cedeu o que nunca teve direito de possuir.\n\nAgora: escreve aos quatro duques indecisos em favor do novo regime.','Pai de Mathis, livre após oito anos como refém da Catedral. Aliado pragmático de Monzai.','Aritmética e confessada','Casa Thorne',{'Inteligência':66}),
 character('caedmon','Sir Caedmon Royce','SirCaedmon','greymoor','Guarda Real · Testemunha neutra','45','73','Veterano de Hallow. Disse não três vezes à espada erguida e ajoelhou-se por escolha, pois recebeu a chance de falar que Rorik negara a um escudeiro.\n\nAgora: acompanha Oriane e Mallory com doze guardas rumo a Greymoor. Pode participar do campeonato se voltar a tempo.','Pai de Miren, 14. Serve como testemunha neutra de Oriane.','Ao juramento escolhido','Guarda Real / Coroa'),
 character('mathis','Mathis Thorne','','thornwick','Herdeiro resgatado · Sem função','19','Inteligência 71','Refém da Catedral desde os onze anos, resgatado da Cripta dos Nomes. Falou voluntariamente com o pai pela primeira vez em oito anos. Está livre e ainda não assumiu uma função.','Filho de Varrick Thorne.','Não registrada','Casa Thorne',{'Inteligência':71}),
 character('oriane','Lady Oriane Velarde','','greymoor','Presidente do Conselho','22','Não informado','Eleita presidente do Conselho de cinquenta cadeiras. Ouviu de Monzai a verdade sobre o irmão morto, em vez de uma promessa impossível.\n\nAgora: segue para interceptar o pai em Greymoor, levando oito mil nomes e a Carta com 43 selos.','Filha do Duque Velarde; irmã de Teodric Velarde, falecido. Acompanhada por Caedmon e Mallory.','À Carta e à responsabilidade política','Conselho / Casa Velarde'),
 character('mallory','Aldous Mallory','','greymoor','Arcebispo · Testemunha de Durnholm','71 (antes 91)','Inteligência 79','Sabia há quarenta e um anos que o deus calara, mas continuou os ritos. Confessou a mentira institucional, entregou a Catedral sem condições e exigiu o registro de que sabia o que fazia. Recebeu vinte anos de vida de Monzai; quebrou a própria bengala.','Conduziu o ritual que cegou Celine. Acompanha Oriane e Caedmon.','Compromisso assumido de olhos abertos','Igreja das Passagens',{'Inteligência':79}),
 character('pike','Avery Pike','','capital','Lorde Chanceler','55','Inteligência 74','Dezenove anos assinando decretos de fome para Rorik. Perguntou quem poderia confrontar Monzai quando ela errasse. Redigiu a carta de fundação.\n\nAgora: voltou para o castelo após a partida da comitiva. Levará à primeira sessão a questão da legitimidade do trono sem combate.','Trabalha com Barnaby Finch e Oriane.','À nova ordem constitucional','Chancelaria / Conselho',{'Inteligência':74}),
 character('finch','Barnaby Finch','','capital','Juiz-Mor · Guardião da Carta','60','Inteligência 81','Trinta e um anos de tribunal; negou provimento à Coroa onze vezes. Retirou sua candidatura por não ter força política. Lerá a Carta em cada sessão e interromperá quem a violar, inclusive a rainha.\n\nPróximo capítulo: juiz proposto do campeonato.','Aliado institucional de Pike e Oriane.','À Carta','Tribunal / Conselho',{'Inteligência':81}),
 character('dain','Dain Holloway','','capital','Comandante de batedores','Não informada','Não informado','Comanda os 42 homens da Companhia do Corvo Negro. Dispensados para contar o que viram e depois recontratados como batedores.\n\nAgora: estrada de Caldris Real. Tem algo a provar no campeonato.','Comanda o Corvo Negro.','Contrato de batedores','Companhia do Corvo Negro'),
 character('garrick','Garrick Dunn','','brennford','Portão e rondas','Não informada','Não informado','Arrancou o brasão do peito na mudança de regime. Agora cuida do portão e das rondas de Brennford, sob comando de Lyra.','Subordinado a Lyra Ashvale.','À vila','Brennford'),
 character('velarde','Duque Velarde','','velarde','Duque · Exército em marcha','61','Não informado','Oito mil homens; oito dias de marcha no registro textual. Veterano de três guerras. Perdeu o filho Teodric aos onze, há seis anos. Desconfia do que parece gratuito e pode interpretar o banquete como armadilha.','Pai de Oriane; pai de Teodric Velarde, falecido. Não confundir o filho com Teodric Hale.','À própria casa','Casa Velarde'),
 character('harrow','Duque Harrow','','harrow','Duque · Exército em marcha','Não informada','Não informado','Seis mil homens em marcha. Onze dias no compêndio; o mapa apresenta outra duração. Perfil pessoal desconhecido.','Um dos três duques em marcha.','Não registrada','Casa Harrow'),
 character('brandt','Duquesa Ilsa Brandt','','brandt','Comandante ducal','Não informada','Não informado','Quatro mil homens. A melhor comandante viva de Caldris. O menor exército entre os três em marcha e a maior ameaça militar real.','Uma dos três governantes em marcha.','Não registrada','Casa Brandt'),
 character('rorik','Rorik Caldris IV','','','Rei foragido','32','Não informado','Fugiu com guarda pessoal e tesouro portátil após o depoimento de Mallory. Enforcou um escudeiro por entornar vinho. Pagou mil homens por dezessete anos para vigiar uma ruína supostamente vazia.\n\nLocalização desconhecida: sem marcador no mapa.','Antiga Coroa; adversário da nova ordem.','Ao trono perdido','Antiga Coroa'),
 character('hale','Teodric Hale','','capital','Inquisidor preso','Não informada','91','Destreza 91, quatro círculos tatuados, sem registro oficial de existência. Esperou dezessete anos pela morte da criatura para colher as almas. Tentou fazer de sua própria morte o último preço cobrado pela Igreja; foi impedido.\n\nAgora: preso em Caldris Real com os dez. Cento e vinte lâminas de cobrança aguardam fundição.','Adversário de Monzai. Distinto de Teodric Velarde, irmão de Oriane.','À estrutura de cobrança da antiga Igreja','Inquisição',{'Destreza':91})
];
// Spread markers around each location instead of stacking them on the same coordinate.
for (const loc of locations) characters.filter(c=>c.locationId===loc.id).forEach((c,i)=>{c.positions[mapId]={x:Math.max(1,Math.min(99,loc.x+(i%3-1)*4.8)),y:loc.y+Math.floor(i/3)*6};});
const chapter=(id,title,period,status,body,characterIds)=>({id,title,period,status,body,characterIds});
const chapters=[
 chapter('ch1','I · A Desgarrada da Velmoor','Dias 1–8','Concluído','A descida de Momo e a tomada de Aethran. Lyra a encontra na floresta; os lobos fogem. A Guilda registra Rank 0. Borin conta a história de Durnholm. Na capela de Brennford, Celine recupera os olhos. Na missa, arranca a faixa; um sopro cura a vila. Garrick abandona o brasão antigo. Borin e Lyra são elevados a Rank 100. Sete dias de treino deixam uma cerca, um estábulo e parte de um celeiro destruídos.\n\nVITÓRIA\nUma vila inteira curada e leal.\n\nREVIRAVOLTA\nDois aliados recebem poder que excede a escala oficial da Guilda.', ['momo','lyra','celine','borin','garrick']),
 chapter('ch2','II · A Ponte, a Jaula e a Cidade Curada','Dias 8–11','Concluído','A mesa na Ponte de Pedra Velha recebe Varrick. A espada de Borin percorre quatro quilômetros. Os 42 mercenários são dispensados para contar o que viram. Brennford é selada. Yuki é libertada da jaula de Thornwick. Vesk chega com suas perguntas. Mallory confessa décadas de silêncio divino e entrega a Catedral. Monzai lhe devolve vinte anos de vida.\n\nMil e duzentas pessoas são curadas; Anneke Ritter recupera a voz após 49 anos. Caedmon diz não três vezes e jura por escolha. O Guardião é desfeito, a Cripta esvaziada e Mathis resgatado. Chega a notícia de que o muro de Durnholm caiu de dentro.\n\nVITÓRIA\nA Igreja é absorvida sem batalha.\n\nPERDA\nA linguagem de posse de Momo põe em dúvida sua generosidade.\n\nREVIRAVOLTA\nOs selos eram feitos de preço. Entre os 63 rompidos estava o que continha Durnholm.', ['momo','borin','varrick','yuki','vesk','mallory','caedmon','mathis']),
 chapter('ch3','III · Durnholm','Dias 11–20','Concluído','Um salto de 85 quilômetros leva à cidade onde todos respiram no mesmo ritmo. A criatura sem rosto não se defende: “eu só não sei soltar.” Momo a decapita e absorve o nó. 8.840 respirações cessam juntas. Dez Inquisidores aplaudem no muro.\n\nDurante sete dias, Monzai permanece na praça, devolvendo almas uma a uma. Lyra conta quatro mil extrações. Um padeiro deixa pão ao seu lado. A comitiva reúne os aliados. Vesk descobre que a lâmina é desnecessária. Em dez minutos, a cidade inteira desperta.\n\nNa fúria, Momo prende Hale à parede. Lyra e Yuki a trazem de volta antes que mate um ser humano.\n\nVITÓRIA\nA maior ressurreição conhecida: 8.840 pessoas.\n\nPERDA\nMomo matou uma criatura que pedia ajuda.\n\nREVIRAVOLTA\nA entidade não atacara a cidade: caíra sobre ela depois de ser esvaziada pelo irmão.', ['momo','lyra','yuki','borin','vesk','elric','hale','celine','mallory']),
 chapter('ch4','IV · O Trono Vazio','Dias 20–26','Concluído','Rorik foge e Mallory depõe. Monzai, Lyra e Celine assumem seus noivados. A barreira seletiva protege 70 mil habitantes sem impedir a circulação de pessoas. Um banquete conjurado abala a corte. Pike pergunta: “com que direito?” Oriane ouve a verdade sobre o irmão.\n\nNasce o Conselho de cinquenta cadeiras. A cláusula do impedimento proíbe o voto em causa própria, incluindo a rainha na própria deposição. Vane recupera a visão. Oriane é eleita presidente. Às 23h a Carta recebe 43 selos.\n\nVITÓRIA\nUm reino legalmente obtido sem sangue de súdito.\n\nREVIRAVOLTA\nA rainha mais poderosa funda um parlamento e se submete a ele.\n\nÚLTIMA CENA · 02H\nNo pátio norte, sob Selhine e Vorrath, Momo e Celine finalmente têm um instante de descanso. Oriane, Caedmon, Mallory e a escolta partiram há vinte minutos rumo a Greymoor. Pike voltou ao castelo. O degrau rachado do trono aguarda o pedreiro pela manhã.', ['momo','celine','oriane','pike','finch','caedmon','mallory','rorik']),
 chapter('ch5','V · O Campeonato de Batalhas','A partir do dia 27 · Proposta','Rascunho','GANCHO\nTrês exércitos não podem atravessar a barreira, mas podem acampar, passar fome e saquear aldeias. O inverno chega em seis semanas. A Carta não convence todos os capitães. A proposta: que campeões lutem diante de todos por cadeiras, títulos e terras.\n\nARENA\nCampo do Leão, fora dos muros de Caldris, em um anel de barreira que permite campeões e impede exércitos.\n\nREGRAS A DELIBERAR\nBarnaby Finch é o juiz proposto. Monzai não pode julgar luta da qual participe. Sua própria participação divide o Conselho. O prêmio principal ainda não foi anunciado. Critérios de vitória e proteção dos participantes ainda precisam ser definidos.\n\nPOSSÍVEIS PARTICIPANTES\nCampeões ducais, guildas e paróquias; Dain e o Corvo Negro, Caedmon se voltar a tempo, Borin, Lyra, Yuki e o imprevisível Vesk. Inscrições ainda não confirmadas.\n\nTENSÕES\nOriane pode retornar ao lado do pai e de oito mil lanças. O Rank 100 de Celine pode ser revelado. Rorik permanece solto, Hale está preso e o Terceiro ainda existe.\n\n“Eu não quero que oito mil filhos de Caldris sangrem na neve do inverno por causa do orgulho de uma coroa.”', ['momo','finch','oriane','lyra','borin','yuki','vesk','caedmon','dain','celine'])
];
const records=(prefix,rows)=>rows.map(([title,status,body],i)=>({id:`${prefix}${i}`,title,status,body}));
export function seedState() {
 return structuredClone({schemaVersion:1,revision:0,campaigns:[{id:'voz-que-devolve',name:'A Voz Que Devolve',subtitle:'Crônica de Monzai Dragon',day:'Dia 26 da Lua Pálida · 02h',updatedAt:'2026-10-31T00:00:00Z',maps:[{id:mapId,name:'Caldris e terras vizinhas',image:'assets/Mapa.webp'}],locations,characters,chapters,
 factions:records('f',[
 ['A Coroa','Reconstrução','Monzai é rainha por Carta com 43 selos. Rorik está foragido com guarda e tesouro portátil. Brasão do reino: corvo sobre espada; símbolo da Coroa: leão branco.'],
 ['Conselho do Reino','Fundado','50 cadeiras. Presidente: Lady Oriane Velarde. O voto da rainha vale tanto quanto qualquer outro. A maioria pode depô-la; ninguém vota em causa própria. Uma cadeira está reservada a Velarde.'],
 ['Igreja das Passagens','Absorvida','Mallory confessou a mentira de quatro séculos. Catedral entregue sem condições. Tribunal desfeito e preço sagrado abolido. Celine é a autoridade eclesiástica máxima da Marca. Dez Inquisidores presos; Vesk desertou.'],
 ['Sete ducados','Em tensão','Velarde marcha com 8.000; Harrow, 6.000; Brandt, 4.000. Quatro duques aguardam o resultado. Varrick lhes escreve em favor do novo regime.'],
 ['Companhia do Corvo Negro','Batedores','42 homens sob Dain Holloway. Dispensados para divulgar o que viram e depois recontratados como batedores.'],
 ['Guarda Real','Juramento voluntário','Caedmon Royce escolheu jurar. Doze guardas acompanham a comitiva de Oriane.']]),
 threads:records('t',[
 ['Greymoor: a filha e o duque','Urgente','Oriane deve interceptar o pai em quatro dias, com oito mil nomes, a Carta, Caedmon e Mallory. Um retorno ao lado do exército ainda é possibilidade, não fato.'],
 ['O inverno e os três exércitos','Urgente','18 mil homens em marcha. A barreira impede a entrada, mas não a fome nos acampamentos. O inverno está a seis semanas. O campeonato é uma proposta de solução.'],
 ['O Terceiro','Mistério','A Cripta nomeia Aethran, o Segundo e o Terceiro. Duas almas estão em Momo. Uma permanece fora. Não está confirmado qual das duas últimas foi absorvida em Durnholm. Vesk investiga.'],
 ['O “ELE” do nono relatório','Mistério','Nove Inquisidores morreram em Durnholm. O último escreveu “ELE ESTÁ COMENDO.” As outras linhas diziam “ela”. O significado permanece desconhecido.'],
 ['A ruína vigiada por Rorik','Mistério','Por que o rei pagou mil homens durante dezessete anos para vigiar uma ruína supostamente vazia? Paradeiro do rei desconhecido.'],
 ['A crise dos 8.840','Em andamento','Elric precisa resolver o estado jurídico das pessoas ressuscitadas. Borin mantém a ordem; Yuki vigia o perímetro.'],
 ['Teodric Hale e as lâminas','Em andamento','Hale e os dez estão presos na capital. Ele queria morrer e foi impedido. 120 lâminas de cobrança aguardam fundição.'],
 ['O poder de Celine','Segredo do mestre','Rank 100 em todos os atributos, desconhecido pela corte. O campeonato pode mudar sua posição pública.'],
 ['A questão dos herdeiros divinos','Mistério','Vesk não encontrou registros de filhos das entidades em quatrocentos anos. Ausência deliberada de registro é uma hipótese, não uma conclusão.'],
 ['Lealdade ou posse?','Em andamento','Monzai nunca respondeu o que acontece com quem não lhe for leal. Lyra, Celine e Mallory já questionaram sua linguagem de propriedade e serviço.'],
 ['Continuidade: idade de Celine','A confirmar','O perfil diz 20 e poucos; o diálogo menciona 26; cegueira desde os 13 por 19 anos sugere 32. Defina o cânone sem apagar os registros anteriores.'],
 ['Continuidade: calendário e distâncias','A confirmar','O panorama fala em onze dias de ascensão, mas a cronologia chega ao dia 26. Harrow: oito dias no mapa e onze no texto. Greymoor: três dias no mapa e interceptação em quatro dias no compêndio. As posições no atlas são aproximações editoriais.']]),
 lore:records('l',[
 ['O céu e as leis','Cânone','Selhine é prateada; Vorrath é pálida e azulada. Ambas são visíveis de dia entre as árvores gigantes de casca cinzenta.\n\nCinco atributos: Força, Agilidade, Vitalidade, Inteligência e Destreza. A escala comum vai de 0 a 100; a Guilda classifica oficialmente só até 99. O Grão-Mestre de Caldris é 94. Um mago Rank 80 conjura um pão e desmaia. Seis magos produziram uma carroça vazia que durou nove minutos.\n\nMomo possui 9.999.999 em tudo, imperceptível aos demais. A escala não implica cálculo automático de combate.'],
 ['O plano mestre','Cânone','Curar antes de exigir. Tornar-se indispensável e depois recusar o poder absoluto em público. Os mercenários viram narradores do milagre; Caedmon jura por escolha. Comandantes entram armados para descobrir que o aço é irrelevante. A barreira defende a cidade. Conselho com voto igual, deposição por maioria e impedimento em causa própria. A cadeira de Velarde liga a casa ao novo regime.\n\nFragilidade: a generosidade de Monzai ainda aparece em linguagem de posse. O paralelo com Aethran foi apontado pelos aliados.'],
 ['Milagres e conquistas','Cânone','Celine: dezenove anos de cegueira desfeitos. Brennford: cura coletiva. Thornwick: 1.200 curados; um braço perdido há oito anos devolvido, e Anneke Ritter fala após 49 anos. Mallory: rejuvenescimento de 91 para 71. Durnholm: 8.840 vidas devolvidas. Hesper Vane: visão restaurada após onze anos.\n\nBorin, Lyra e Celine são Rank 100. O Guardião dos Nomes foi desfeito; a entidade de Durnholm foi absorvida. Brennford, Thornwick, Marca Oriental, Durnholm e Caldris Real estão sob influência da rainha.'],
 ['Vínculos e cuidado','Cânone','Lyra contou as extrações para que existisse um fim e ficou ao lado de Momo mesmo ferida. Celine guardou a última conta do rosário e velou por quem curava a todos. Yuki ofereceu a frase “Você já não está lá”. Borin ergueu Monzai com delicadeza. Um padeiro deixou pão ao lado de seu joelho.\n\nLyra e Celine aceitaram os anéis por escolha, preservando o direito de discordar. Seus vínculos não apagam sua autonomia.'],
 ['Carta de fundação','Resumo institucional','Carta selada às 23h por 43 selos. Conselho com 50 cadeiras, presidido por Oriane. Monzai tem um voto igual aos demais e pode ser deposta por maioria. Cláusula do impedimento: ninguém vota em causa própria. Finch lerá a Carta em cada sessão e interromperá as violações.\n\nEste registro é um resumo da campanha, não o texto integral da Carta.'],
 ['Notas do atlas','Referência','As imagens de nove personagens foram fornecidas pelo autor. Fichas sem imagem usam iniciais, sem inventar retratos. O mapa é a referência visual; marcadores são posicionados em percentuais e podem ser ajustados. A comitiva de Greymoor tem posição aproximada; Rorik permanece sem marcador por paradeiro desconhecido. O Campo do Leão tem posição editorial proposta.\n\nO próximo capítulo é planejamento. Nenhum confronto ou resultado do campeonato foi inventado. Os resumos preservam fatos de campanha e vínculos não explícitos; não são uma transcrição integral do compêndio.']]),
 tournament:{rules:'PROPOSTA · CAMPO DO LEÃO\nDisputas por cadeiras do Conselho, títulos e terras. O prêmio principal não foi anunciado. Campeões de casas, guildas, paróquias e inscrições abertas. Juiz proposto: Barnaby Finch.\n\nA cláusula do impedimento proíbe Monzai de julgar a própria luta. Sua participação ainda depende de deliberação. Critérios de vitória, segurança e composição das chaves permanecem em aberto.\n\nPossíveis participantes: campeões ducais, Dain, Caedmon (se retornar), Borin, Lyra, Yuki e Vesk. Nenhuma inscrição ou luta está confirmada.',matches:[]}
 }]});
}
